      "title": "European Working Conditions Survey, 2015",
      "url_or_doi": "https://doi.org/10.5255/UKDA-SN-8098-5",
      "justification": "Conducted by Eurofound, the 6th wave of the European Working Conditions Survey (EWCS) surveyed nearly 44,000 workers across 35 European countries in 2015. It provides harmonized microdata on working conditions, physical and psychosocial risk factors, occupational health and safety, work-life balance, and job quality during the 2010s."
    },
    {
      "title": "European Working Conditions Survey, 2010",
      "url_or_doi": "https://doi.org/10.5255/UKDA-SN-6971-2",
      "justification": "The 5th edition of Eurofound's EWCS, carried out in 2010, interviewed workers in 34 European countries. It covers occupational health risks, physical working environment, psychosocial factors, working time, and employee well-being across the target European countries."
    },
    {
      "title": "Second European Survey of Enterprises on New and Emerging Risks (ESENER-2), 2014",
      "url_or_doi": "https://doi.org/10.5255/UKDA-SN-7808-1",
      "justification": "Carried out in 2014 by the European Agency for Safety and Health at Work (EU-OSHA), ESENER-2 provides establishment-level data across 36 European countries on occupational safety and health (OSH) management, psychosocial risks, workplace stress, and health and safety practices."
    },
    {
      "title": "Third European Survey of Enterprises on New and Emerging Risks (ESENER-3), 2019",
      "url_or_doi": "https://doi.org/10.5255/UKDA-SN-8690-1",
      "justification": "Conducted by EU-OSHA in 2019 across European nations, this dataset focuses on workplace management of occupational health and safety risks, emerging psychosocial risk factors, drivers and barriers to OSH management, and employee participation in safety measures."
    }
  ]
}
